cat << 'EOF' > src/orchestration/tools/registry.test.ts
import {ToolRegistry} from './registry.js';

describe('ToolRegistry validation of extra properties', () => {
  it('passes the input object through unchanged including undeclared extra properties', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'echo',
        description: 'echoes',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async (input) => {
        executorInputs.push(input);
        return 'ok';
      }
    );

    await registry.execute('echo', {a: 'hello', b: 'extra'});
    expect(executorInputs).toEqual([{a: 'hello', b: 'extra'}]);
  });
});
EOF
